package com.shiphappens.logistics.service;
import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.entity.Statuses.UserRole; import com.shiphappens.logistics.exception.ApiException; import com.shiphappens.logistics.repository.AppUserRepository; import com.shiphappens.logistics.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final AppUserRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthService(AppUserRepository users,PasswordEncoder passwords,JwtService jwt){this.users=users;this.passwords=passwords;this.jwt=jwt;} @Transactional public AppUser register(String email,String password,UserRole role){if(users.findByEmail(email).isPresent())throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_EMAIL","An account already exists for this email");AppUser user=new AppUser();user.setEmail(email);user.setPasswordHash(passwords.encode(password));user.setRole(role);return users.save(user);} public LoginResult login(String email,String password){AppUser user=users.findByEmail(email.toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password"));if(!user.isEnabled()||!passwords.matches(password,user.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password");return new LoginResult(jwt.create(user.getEmail(),user.getRole().name(),user.getId()),user.getEmail(),user.getRole().name());} public record LoginResult(String accessToken,String email,String role){} }
